const svg=$('#kernels-svg'), out=$('#kernels-out'), kind=$('#kernels-kind'), p1=$('#kernels-p1'), p1L=$('#kernels-p1-lbl');
const W=640,H=300,padL=52,padR=20,padT=22,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const xmin=-3,xmax=3;          // 1D inputs
const center=0.6;              // x0 for k(x0, .)
function applyDefaults(){
  const m={linear:{min:0.2,max:4,step:0.1,init:1},poly:{min:1,max:6,step:1,init:2},rbf:{min:0.2,max:4,step:0.1,init:1}}[kind.value];
  p1.min=m.min;p1.max=m.max;p1.step=m.step;p1.value=m.init;
}
function k(a,b){
  const v=+p1.value;
  if(kind.value==='linear') return a*b;
  if(kind.value==='poly') return Math.pow(a*b+1, v);
  return Math.exp(-((a-b)*(a-b))/(2*v*v));        // rbf
}
// small sample Gram matrix + smallest eigenvalue via Jacobi (symmetric)
function gram(){
  const xs=[-2,-1,-0.3,0.4,1.2,2.1];
  const n=xs.length, A=[];
  for(let i=0;i<n;i++){ A.push([]); for(let j=0;j<n;j++) A[i].push(k(xs[i],xs[j])); }
  return {A,n};
}
function eigMinMax(A,n){
  // Jacobi eigenvalue iteration on a symmetric matrix
  const M=A.map(r=>r.slice());
  for(let sweep=0;sweep<60;sweep++){
    let p=0,q=1,off=0;
    for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){ if(Math.abs(M[i][j])>off){ off=Math.abs(M[i][j]); p=i; q=j; } }
    if(off<1e-10) break;
    const app=M[p][p],aqq=M[q][q],apq=M[p][q];
    const phi=0.5*Math.atan2(2*apq, aqq-app);
    const c=Math.cos(phi), s=Math.sin(phi);
    for(let i=0;i<n;i++){ const mip=M[i][p],miq=M[i][q]; M[i][p]=c*mip-s*miq; M[i][q]=s*mip+c*miq; }
    for(let i=0;i<n;i++){ const mpi=M[p][i],mqi=M[q][i]; M[p][i]=c*mpi-s*mqi; M[q][i]=s*mpi+c*mqi; }
  }
  const ev=[]; for(let i=0;i<n;i++) ev.push(M[i][i]);
  return {min:Math.min(...ev), max:Math.max(...ev)};
}
function render(){
  svg.innerHTML='';
  const v=+p1.value;
  p1L.textContent = kind.value==='poly' ? ('degree d = '+v) : (kind.value==='rbf' ? ('σ = '+v.toFixed(1)) : ('(unused for linear)'));
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:(y0+y1)/2,x2:x1,y2:(y0+y1)/2,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:x0+(center-xmin)/(xmax-xmin)*(x1-x0),y1:y1,x2:x0+(center-xmin)/(xmax-xmin)*(x1-x0),y2:y0,stroke:'var(--line)','stroke-dasharray':'3 5',opacity:0.6}));
  // value range for y-scaling
  const vals=[]; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; vals.push(k(center,x)); }
  const vmax=Math.max(...vals,0.01), vmin=Math.min(...vals,-0.01);
  const SX=x=>x0+(x-xmin)/(xmax-xmin)*(x1-x0);
  const SY=val=>y0+(val-vmin)/((vmax-vmin)||1)*(y1-y0);
  let dpath='M';
  for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; dpath+=' '+SX(x).toFixed(1)+' '+SY(k(center,x)).toFixed(1); }
  svg.appendChild(SVG('path',{d:dpath,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // mark center
  svg.appendChild(SVG('circle',{cx:SX(center),cy:SY(k(center,center)),r:4,fill:'var(--cyan)'}));
  const lbl=SVG('text',{x:SX(center),y:SY(k(center,center))-9,'text-anchor':'middle','font-size':11,fill:'var(--cyan)'}); lbl.textContent='x₀='+center; svg.appendChild(lbl);
  const cap=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='second argument  →   curve is k(x₀, ·)'; svg.appendChild(cap);
  const {A,n}=gram(); const {min,max}=eigMinMax(A,n);
  out.textContent =
    'kernel: '+kind.value+(kind.value==='poly'?('  (degree '+v+')'):(kind.value==='rbf'?('  (σ = '+v.toFixed(1)+')'):''))+'\n'+
    'k(x₀,x₀) = '+k(center,center).toFixed(3)+'\n'+
    '6×6 sample Gram matrix eigenvalues:  min = '+min.toFixed(4)+',  max = '+max.toFixed(4)+'\n'+
    (min>=-1e-6 ? 'min eigenvalue ≥ 0  ⇒  Gram is PSD ✓  (valid PD kernel)' : 'NEGATIVE eigenvalue ✗  — not a valid kernel here');
}
kind.addEventListener('change',()=>{ applyDefaults(); render(); });
p1.addEventListener('input',render);
applyDefaults(); render();

const svg=$('#rkhs-svg'), out=$('#rkhs-out'), q=$('#rkhs-q'), qL=$('#rkhs-q-lbl'), sig=$('#rkhs-sig'), sigL=$('#rkhs-sig-lbl');
const flip=$('#rkhs-flip'), reset=$('#rkhs-reset');
const W=640,H=300,padL=46,padR=20,padT=20,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const xmin=-3,xmax=3;
let bumps=[{c:-1,a:1},{c:1,a:-1}]; // {center, alpha}
function k(a,b){ const s=+sig.value; return Math.exp(-((a-b)*(a-b))/(2*s*s)); }
function f(x){ let s=0; for(const b of bumps) s+=b.a*k(b.c,x); return s; }
const SX=x=>x0+(x-xmin)/(xmax-xmin)*(x1-x0);
function render(){
  svg.innerHTML='';
  const qx=+q.value;
  qL.textContent='x = '+qx.toFixed(2);
  sigL.textContent='σ = '+(+sig.value).toFixed(1);
  // y range
  const vals=[]; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; vals.push(f(x)); }
  const vmax=Math.max(...vals,0.5), vmin=Math.min(...vals,-0.5);
  const SY=v=>y0+(v-vmin)/((vmax-vmin)||1)*(y1-y0);
  // zero axis
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--line)'}));
  // individual bumps faint
  for(const b of bumps){ let dp='M'; for(let i=0;i<=160;i++){ const x=xmin+(xmax-xmin)*i/160; dp+=' '+SX(x).toFixed(1)+' '+SY(b.a*k(b.c,x)).toFixed(1); } svg.appendChild(SVG('path',{d:dp,fill:'none',stroke:'var(--violet)','stroke-width':1,opacity:0.5,'stroke-dasharray':'3 3'})); }
  // total f
  let dpath='M'; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; dpath+=' '+SX(x).toFixed(1)+' '+SY(f(x)).toFixed(1); }
  svg.appendChild(SVG('path',{d:dpath,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // bump centers
  for(const b of bumps) svg.appendChild(SVG('circle',{cx:SX(b.c),cy:SY(0),r:4,fill:b.a>=0?'var(--cyan)':'var(--pink)'}));
  // query vertical + dot
  svg.appendChild(SVG('line',{x1:SX(qx),y1:y1,x2:SX(qx),y2:y0,stroke:'var(--green)','stroke-dasharray':'4 4'}));
  svg.appendChild(SVG('circle',{cx:SX(qx),cy:SY(f(qx)),r:5,fill:'var(--green)'}));
  // two evaluations
  const direct=f(qx);
  let inner=0; for(const b of bumps) inner+=b.a*k(b.c,qx); // <f, k(x,.)> = Σ α_i k(x_i, x)
  let normsq=0; for(const bi of bumps) for(const bj of bumps) normsq+=bi.a*bj.a*k(bi.c,bj.c);
  out.textContent =
    'bumps: '+bumps.map(b=>b.a.toFixed(0)+'·k('+b.c+',·)').join('  +  ')+'\n'+
    'evaluate f at x:        f(x) = Σ αᵢ k(xᵢ,x) = '+direct.toFixed(4)+'\n'+
    'RKHS inner product:  ⟨f, k(x,·)⟩ = Σ αᵢ ⟨k(xᵢ,·), k(x,·)⟩ = Σ αᵢ k(xᵢ,x) = '+inner.toFixed(4)+'\n'+
    'the middle step is the reproducing property ⟨k(xᵢ,·), k(x,·)⟩ = k(xᵢ,x) — which is exactly why the inner product equals the evaluation '+(Math.abs(direct-inner)<1e-9?'✓':'✗')+'\n'+
    '‖f‖²_H = αᵀKα = '+normsq.toFixed(4)+'   (RKHS norm — a smoothness penalty)';
}
q.addEventListener('input',render); sig.addEventListener('input',render);
flip.addEventListener('click',()=>{ if(bumps.length){ bumps[bumps.length-1].a*=-1; render(); } });
reset.addEventListener('click',()=>{ bumps=[{c:-1,a:1},{c:1,a:-1}]; render(); });
// click on the plot adds a bump at the nearest of three preset centers
svg.addEventListener('click',e=>{
  const r=svg.getBoundingClientRect();
  const px=(e.clientX-r.left)/r.width*W;
  const xData=xmin+(px-x0)/((x1-x0)||1)*(xmax-xmin);
  if(xData<xmin||xData>xmax) return;
  bumps.push({c:Math.round(xData*2)/2, a:1});
  render();
});
render();

const svg=$('#rep-svg'), out=$('#rep-out'), lam=$('#rep-lam'), lamL=$('#rep-lam-lbl'), sig=$('#rep-sig'), sigL=$('#rep-sig-lbl'), resample=$('#rep-resample');
const W=640,H=320,padL=48,padR=20,padT=22,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const xmin=0,xmax=1;
let pts=[]; // {x,y}
function truth(x){ return Math.sin(2*Math.PI*x); }
function gen(){ pts=[]; const n=7; for(let i=0;i<n;i++){ const x=(i+0.5)/n; pts.push({x, y:truth(x)+(Math.random()-0.5)*0.5}); } }
function k(a,b){ const s=+sig.value; return Math.exp(-((a-b)*(a-b))/(2*s*s)); }
// Gaussian elimination solver for (K+λI) α = y
function solve(A,b){ const n=b.length; const M=A.map((r,i)=>[...r,b[i]]);
  for(let c=0;c<n;c++){ let piv=c; for(let r=c+1;r<n;r++) if(Math.abs(M[r][c])>Math.abs(M[piv][c])) piv=r; [M[c],M[piv]]=[M[piv],M[c]];
    const d=M[c][c]||1e-12; for(let j=c;j<=n;j++) M[c][j]/=d;
    for(let r=0;r<n;r++){ if(r===c) continue; const fct=M[r][c]; for(let j=c;j<=n;j++) M[r][j]-=fct*M[c][j]; } }
  return M.map(r=>r[n]); }
function fitAlpha(){
  const n=pts.length, K=[], y=[];
  for(let i=0;i<n;i++){ K.push([]); for(let j=0;j<n;j++) K[i].push(k(pts[i].x,pts[j].x)); y.push(pts[i].y); }
  const lamv=+lam.value; const A=K.map((r,i)=>r.map((v,j)=>v+(i===j?lamv:0)));
  return {alpha:solve(A,y), K};
}
function predict(alpha,x){ let s=0; for(let i=0;i<pts.length;i++) s+=alpha[i]*k(pts[i].x,x); return s; }
const SX=x=>x0+(x-xmin)/(xmax-xmin)*(x1-x0);
function render(){
  svg.innerHTML='';
  lamL.textContent='λ = '+(+lam.value).toFixed(3);
  sigL.textContent='σ = '+(+sig.value).toFixed(2);
  const {alpha}=fitAlpha();
  const SY=v=>y0+(v-(-1.8))/(3.6)*(y1-y0); // fixed [-1.8,1.8]
  // zero axis + frame
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  // truth dashed
  let dt='M'; for(let i=0;i<=160;i++){ const x=xmin+(xmax-xmin)*i/160; dt+=' '+SX(x).toFixed(1)+' '+SY(truth(x)).toFixed(1); }
  svg.appendChild(SVG('path',{d:dt,fill:'none',stroke:'var(--mute)','stroke-width':1.3,'stroke-dasharray':'5 4'}));
  // fit
  let df='M'; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; df+=' '+SX(x).toFixed(1)+' '+SY(predict(alpha,x)).toFixed(1); }
  svg.appendChild(SVG('path',{d:df,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // data
  for(const p of pts) svg.appendChild(SVG('circle',{cx:SX(p.x),cy:SY(p.y),r:4,fill:'var(--blue)'}));
  // legend
  function leg(x,y,c,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+20,y2:y,stroke:c,'stroke-width':2.2})); const tt=SVG('text',{x:x+26,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x1-160,y1+6,'var(--mute)','truth sin(2πx)'); leg(x1-160,y1+22,'var(--yellow)','kernel ridge fit');
  const cap=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='x'; svg.appendChild(cap);
  out.textContent =
    'n = '+pts.length+' points,  σ = '+(+sig.value).toFixed(2)+',  λ = '+(+lam.value).toFixed(3)+'\n'+
    'solved α = (K + λI)⁻¹ y  via Gaussian elimination\n'+
    'α = ['+alpha.map(a=>a.toFixed(2)).join(', ')+']\n'+
    (+lam.value<0.02 ? 'λ→0: f interpolates the noisy data (wiggly, low bias / high variance)' :
     (+lam.value>1 ? 'large λ: f is heavily smoothed toward 0 (high bias / low variance)' :
     'moderate λ: f tracks the underlying sin(2πx)'));
}
lam.addEventListener('input',render); sig.addEventListener('input',render);
resample.addEventListener('click',()=>{ gen(); render(); });
gen(); render();

const svg=$('#svm-svg'), out=$('#svm-out'), kern=$('#svm-kernel'), CSl=$('#svm-C'), CL=$('#svm-C-lbl'), sig=$('#svm-sig'), sigL=$('#svm-sig-lbl'), resample=$('#svm-resample');
const W=640,H=360,padL=30,padR=30,padT=20,padB=20;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const dmin=-3.2,dmax=3.2;
let pts=[]; // {x,y,label}
function gen(){
  pts=[];
  for(let i=0;i<7;i++) pts.push({x:-1.4+(Math.random()-0.5)*2.0, y:0.2+(Math.random()-0.5)*3.0, label:1});
  for(let i=0;i<7;i++) pts.push({x: 1.4+(Math.random()-0.5)*2.0, y:-0.2+(Math.random()-0.5)*3.0, label:-1});
}
function k(a,b){
  if(kern.value==='linear') return a.x*b.x+a.y*b.y;
  const s=+sig.value; const dx=a.x-b.x, dy=a.y-b.y; return Math.exp(-(dx*dx+dy*dy)/(2*s*s));
}
// Train the dual by simplified SMO-style projected coordinate ascent on α (0<=α<=C, Σ α_i y_i = 0).
let alpha=[], bbias=0;
function train(){
  const n=pts.length, C=+CSl.value;
  alpha=new Array(n).fill(0);
  const K=[]; for(let i=0;i<n;i++){ K.push([]); for(let j=0;j<n;j++) K[i].push(k(pts[i],pts[j])); }
  const y=pts.map(p=>p.label);
  function fval(i){ let s=0; for(let j=0;j<n;j++) s+=alpha[j]*y[j]*K[i][j]; return s+bbias; }
  // SMO: optimize pairs (i,j)
  for(let pass=0;pass<400;pass++){
    let changed=0;
    for(let i=0;i<n;i++){
      const Ei=fval(i)-y[i];
      if((y[i]*Ei<-1e-3 && alpha[i]<C)||(y[i]*Ei>1e-3 && alpha[i]>0)){
        let j=(i+1+Math.floor(Math.random()*(n-1)))%n;
        const Ej=fval(j)-y[j];
        const ai=alpha[i], aj=alpha[j];
        let L,Hh;
        if(y[i]!==y[j]){ L=Math.max(0,aj-ai); Hh=Math.min(C,C+aj-ai); }
        else { L=Math.max(0,ai+aj-C); Hh=Math.min(C,ai+aj); }
        if(L===Hh) continue;
        const eta=2*K[i][j]-K[i][i]-K[j][j];
        if(eta>=0) continue;
        let ajn=aj-y[j]*(Ei-Ej)/eta;
        ajn=Math.min(Hh,Math.max(L,ajn));
        if(Math.abs(ajn-aj)<1e-6) continue;
        const ain=ai+y[i]*y[j]*(aj-ajn);
        // bias update
        const b1=bbias-Ei-y[i]*(ain-ai)*K[i][i]-y[j]*(ajn-aj)*K[i][j];
        const b2=bbias-Ej-y[i]*(ain-ai)*K[i][j]-y[j]*(ajn-aj)*K[j][j];
        alpha[i]=ain; alpha[j]=ajn;
        if(ain>0&&ain<C) bbias=b1; else if(ajn>0&&ajn<C) bbias=b2; else bbias=(b1+b2)/2;
        changed++;
      }
    }
    if(changed===0) pass+= (pass>30?400:0);
  }
}
function decide(qx,qy){ const n=pts.length; let s=0; for(let j=0;j<n;j++) s+=alpha[j]*pts[j].label*k(pts[j],{x:qx,y:qy}); return s+bbias; }
const SX=x=>x0+(x-dmin)/(dmax-dmin)*(x1-x0);
const SY=y=>y0+(y-dmin)/(dmax-dmin)*(y1-y0); // note y axis flipped via y0->y1
function render(){
  svg.innerHTML='';
  CL.textContent='C = '+(+CSl.value).toFixed(1);
  sigL.textContent = kern.value==='rbf' ? ('σ = '+(+sig.value).toFixed(1)) : '(linear: σ unused)';
  train();
  // decision-region shading via a coarse grid
  const G=40;
  for(let gi=0;gi<G;gi++) for(let gj=0;gj<G;gj++){
    const gx=dmin+(dmax-dmin)*(gi+0.5)/G, gy=dmin+(dmax-dmin)*(gj+0.5)/G;
    const d=decide(gx,gy);
    const col = d>=0 ? 'rgba(125,224,214,0.10)' : 'rgba(224,122,95,0.10)';
    svg.appendChild(SVG('rect',{x:SX(gx-( dmax-dmin)/(2*G)),y:SY(gy+(dmax-dmin)/(2*G)),width:(x1-x0)/G+1,height:(y0-y1)/G+1,fill:col}));
  }
  // boundary + margins via marching the grid for level sets d = 0, ±1 (draw small segments where sign flips)
  function drawLevel(level,color,dash){
    const N=120;
    for(let gi=0;gi<N;gi++){ for(let gj=0;gj<N;gj++){
      const gx=dmin+(dmax-dmin)*gi/N, gy=dmin+(dmax-dmin)*gj/N, h=(dmax-dmin)/N;
      const a=decide(gx,gy)-level, b=decide(gx+h,gy)-level, c=decide(gx,gy+h)-level;
      if(a*b<0){ const t=a/(a-b); svg.appendChild(SVG('circle',{cx:SX(gx+t*h),cy:SY(gy),r:0.9,fill:color})); }
      if(a*c<0){ const t=a/(a-c); svg.appendChild(SVG('circle',{cx:SX(gx),cy:SY(gy+t*h),r:0.9,fill:color})); }
    }}
  }
  drawLevel(0,'var(--yellow)'); drawLevel(1,'var(--mute)'); drawLevel(-1,'var(--mute)');
  // points
  const C=+CSl.value; let nsv=0;
  for(let i=0;i<pts.length;i++){
    const p=pts[i]; const sv=alpha[i]>1e-4;
    if(sv) nsv++;
    const fill=p.label===1?'var(--cyan)':'var(--pink)';
    if(sv) svg.appendChild(SVG('circle',{cx:SX(p.x),cy:SY(p.y),r:9,fill:'none',stroke:'var(--yellow)','stroke-width':2}));
    svg.appendChild(SVG('circle',{cx:SX(p.x),cy:SY(p.y),r:5,fill,stroke:'var(--ink)','stroke-width':1}));
  }
  // legend
  const lg=SVG('text',{x:x0+4,y:y1+10,'font-size':11,fill:'var(--mute)'}); lg.textContent='cyan=+1, pink=−1, ringed=support vector, yellow=boundary, grey=margins'; svg.appendChild(lg);
  let trainErr=0; for(const p of pts) if(Math.sign(decide(p.x,p.y))!==p.label) trainErr++;
  out.textContent =
    'kernel: '+kern.value+(kern.value==='rbf'?('  (σ='+(+sig.value).toFixed(1)+')'):'')+',  C = '+C.toFixed(1)+'\n'+
    'support vectors (α_i > 0): '+nsv+' of '+pts.length+'   bias b = '+bbias.toFixed(3)+'\n'+
    'training misclassifications: '+trainErr+'\n'+
    'decision: g(x) = sign(Σ αᵢyᵢ k(xᵢ,x) + b) — touches data only through the kernel';
}
kern.addEventListener('change',render); CSl.addEventListener('input',render); sig.addEventListener('input',render);
resample.addEventListener('click',()=>{ gen(); render(); });
gen(); render();

const svg=$('#gp-svg'), out=$('#gp-out'), sig=$('#gp-sig'), sigL=$('#gp-sig-lbl'), noise=$('#gp-noise'), noiseL=$('#gp-noise-lbl'), sampleBtn=$('#gp-sample'), reset=$('#gp-reset');
const W=640,H=340,padL=46,padR=20,padT=22,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const xmin=0,xmax=1, ylo=-2.2,yhi=2.2;
let data=[{x:0.2,y:0.7},{x:0.5,y:-0.4},{x:0.8,y:0.9}];
let showSamples=false;
function k(a,b){ const s=+sig.value; return Math.exp(-((a-b)*(a-b))/(2*s*s)); }
function solve(A,b){ const n=b.length; const M=A.map((r,i)=>[...r,b[i]]);
  for(let c=0;c<n;c++){ let piv=c; for(let r=c+1;r<n;r++) if(Math.abs(M[r][c])>Math.abs(M[piv][c])) piv=r; [M[c],M[piv]]=[M[piv],M[c]];
    const d=M[c][c]||1e-12; for(let j=c;j<=n;j++) M[c][j]/=d;
    for(let r=0;r<n;r++){ if(r===c) continue; const fct=M[r][c]; for(let j=c;j<=n;j++) M[r][j]-=fct*M[c][j]; } }
  return M.map(r=>r[n]); }
// returns Kinv (n×n) and y vector
function inverseKy(){
  const n=data.length, Kn=+noise.value;
  const A=[]; for(let i=0;i<n;i++){ A.push([]); for(let j=0;j<n;j++) A[i].push(k(data[i].x,data[j].x)+(i===j?Kn:0)); }
  // build inverse columnwise by solving A x = e_i
  const inv=Array.from({length:n},()=>new Array(n).fill(0));
  for(let c=0;c<n;c++){ const e=new Array(n).fill(0); e[c]=1; const col=solve(A.map(r=>r.slice()),e); for(let r=0;r<n;r++) inv[r][c]=col[r]; }
  const y=data.map(d=>d.y);
  return {inv,y,n};
}
function posterior(xstar,inv,y,n){
  const ks=data.map(d=>k(xstar,d.x));
  let mean=0; for(let i=0;i<n;i++){ let row=0; for(let j=0;j<n;j++) row+=inv[i][j]*y[j]; mean+=ks[i]*row; }
  // variance = k** - ks^T inv ks
  let quad=0; for(let i=0;i<n;i++) for(let j=0;j<n;j++) quad+=ks[i]*inv[i][j]*ks[j];
  const varr=Math.max(0, k(xstar,xstar)-quad);
  return {mean, sd:Math.sqrt(varr)};
}
const SX=x=>x0+(x-xmin)/(xmax-xmin)*(x1-x0);
const SY=v=>y0+(v-ylo)/(yhi-ylo)*(y1-y0);
