const svg=$('#mercer-svg'), out=$('#mercer-out'), DSl=$('#mercer-D'), DL=$('#mercer-D-lbl'), sig=$('#mercer-sig'), sigL=$('#mercer-sig-lbl'), resample=$('#mercer-resample');
const W=640,H=300,padL=48,padR=20,padT=22,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const xmin=-3,xmax=3;
// For RBF exp(-r^2/(2σ^2)) the spectral density is N(0, 1/σ^2). Sample many; use first D.
let freqs=[], phases=[];
function gauss(){ let u=0,v=0; while(u===0)u=Math.random(); while(v===0)v=Math.random(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function resampleFreqs(){ freqs=[]; phases=[]; for(let i=0;i<400;i++){ freqs.push(gauss()/(+sig.value)); phases.push(Math.random()*2*Math.PI); } }
function trueK(x){ const s=+sig.value; return Math.exp(-(x*x)/(2*s*s)); } // k(x,0)
function approxK(x,D){ // (1/D) Σ z(x) z(0),  z=√2 cos(ω·x+b)
  let s=0; for(let r=0;r<D;r++){ const zx=Math.SQRT2*Math.cos(freqs[r]*x+phases[r]); const z0=Math.SQRT2*Math.cos(freqs[r]*0+phases[r]); s+=zx*z0; } return s/D;
}
const SX=x=>x0+(x-xmin)/(xmax-xmin)*(x1-x0);
const SY=v=>y0+(v-(-0.6))/(1.8)*(y1-y0); // range [-0.6, 1.2]
function render(){
  svg.innerHTML='';
  const D=+DSl.value;
  DL.textContent='D = '+D;
  sigL.textContent='σ = '+(+sig.value).toFixed(1);
  // frame
  svg.appendChild(SVG('line',{x1:x0,y1:SY(0),x2:x1,y2:SY(0),stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  // true RBF
  let dt='M'; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; dt+=' '+SX(x).toFixed(1)+' '+SY(trueK(x)).toFixed(1); }
  svg.appendChild(SVG('path',{d:dt,fill:'none',stroke:'var(--cyan)','stroke-width':2.6}));
  // approximation
  let da='M', err=0, cnt=0; for(let i=0;i<=200;i++){ const x=xmin+(xmax-xmin)*i/200; const a=approxK(x,D); da+=' '+SX(x).toFixed(1)+' '+SY(a).toFixed(1); err+=(a-trueK(x))*(a-trueK(x)); cnt++; }
  svg.appendChild(SVG('path',{d:da,fill:'none',stroke:'var(--yellow)','stroke-width':1.8,opacity:0.95}));
  // legend
  function leg(x,y,c,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+20,y2:y,stroke:c,'stroke-width':2.4})); const tt=SVG('text',{x:x+26,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x1-200,y1+6,'var(--cyan)','true RBF k(x,0)'); leg(x1-200,y1+22,'var(--yellow)','random-feature approx (D='+D+')');
  const cap=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); cap.textContent='x   (second argument fixed at 0)'; svg.appendChild(cap);
  const rmse=Math.sqrt(err/cnt);
  out.textContent =
    'D = '+D+' random Fourier features,  σ = '+(+sig.value).toFixed(1)+'\n'+
    'k(x,0) ≈ (1/D) Σ_r √2 cos(ωᵣx+bᵣ)·√2 cos(bᵣ),   ωᵣ ~ N(0, 1/σ²)  (Bochner)\n'+
    'RMS error vs. true RBF over x∈[−3,3]: '+rmse.toFixed(4)+'\n'+
    (D<8 ? 'few features: noisy approximation' : (D>120 ? 'many features: tight — error decays like 1/√D' : 'converging toward the true kernel as D grows'));
}
